using System.IO;
using System.Text.Json;
using System.Windows;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
static class Program{
 static int checks;static JsonElement J<T>(T x)=>JsonSerializer.SerializeToElement(x);static void Check(bool c,string m){if(!c)throw new Exception(m);checks++;}
 static readonly string[] Names=["CalibPointTotalNum","RotPointTotalNum","TeachEnable","TeachFlag","BasePointX","BasePointY","MoveAlignX","MoveAlignY","ChangeDirectionMoveTime","BaseAngle","MoveAngle","UseRelativeCoordinates","CalibOrigin","RefreshFileEnable","CalibPathName","WeightFactor","DistThreshold","SampleRatio"];
 static readonly Dictionary<string,int> Defaults=new(){["HomoFreedom"]=2,["WeightFun"]=3,["WeightFactor"]=20,["DistThreshold"]=30,["SampleRatio"]=60,["CameraMode"]=1};
 [STAThread]static int Main(){try{_=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Scenario(false);Scenario(true);Console.WriteLine($"PASS {checks} Npoint source6-default/18ISub reset checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Scenario(bool reject){var plugin=new NPointPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());values["HomoFreedom"]=J(3);values["CameraMode"]=J(2);values["ImagePointX0"]=J(12.25);values["WorldPointY31"]=J(72.5);values["CalibPointGet"]=J(1);values["RotPointTotalNum"]=J(0);values["CalibPathName"]=J(Path.GetFullPath("analysis/n-point-calibration/keep.xml"));values["RefreshFileEnable"]=J(true);values["DisplaySettings"]=J("");values["ConfigurationUserData"]=J(JsonSerializer.Serialize(Names.ToDictionary(n=>"@"+n,_=>"True").Concat(new[]{new KeyValuePair<string,string>("Keep","value")}).ToDictionary(p=>p.Key,p=>p.Value)));var subs=new Subs();var confirm=new Confirms();var notices=new Notices();int atomic=0,runs=0;bool record=false;
 IReadOnlyDictionary<string,JsonElement> Effective()=>new Dictionary<string,JsonElement>(values);
 var context=new ToolEditorContext(new("reset",NPointPlugin.Id,"1.0.0","Npoint",values),Environment.CurrentDirectory,next=>{if(record&&reject&&next["HomoFreedom"].GetInt32()==2&&values["HomoFreedom"].GetInt32()==3)throw new InvalidOperationException("reject HomoFreedom");values=next;},_=>{runs++;throw new Exception("must not run");}){ReadEffectiveParameters=Effective,ConfigurationSubscriptions=subs,ConfigurationConfirmations=confirm,ConfigurationNotifications=notices,ResetConfigurationParameters=_=>{atomic++;throw new Exception("no atomic");}};
 using var session=plugin.CreateConfiguration(context);var state=session.State;
 foreach(string name in Names){var node=state.Find(name)!;var kind=plugin.Descriptor.Parameters.Single(p=>p.Name==name).Kind;var type=kind==ParameterKind.Text?"string":kind==ParameterKind.Number?"float":"int";subs.Bound[name]=new(new ConfigurationConstantReference(type,"1"),ConfigurationSubscriptionIndex.All);state.ApplySubscription(node,subs.Read(new(ConfigurationSubscriptionDomain.Parameter,name,type)),true);}
 subs.Clears.Clear();var before=values.ToDictionary(p=>p.Key,p=>p.Value.GetRawText());confirm.Allow=false;state.Invoke(state.Find("Button_ResetAlgoParams")!);Check(subs.Clears.Count==0&&before.All(p=>values[p.Key].GetRawText()==p.Value),"cancel no mutation");confirm.Allow=true;record=true;state.Invoke(state.Find("Button_ResetAlgoParams")!);record=false;
 Check(subs.Clears.SequenceEqual(Names),"18 source ISUB order including persisted-only modes");Check(atomic==0&&runs==0,"reset neither atomic nor run");foreach(var p in Defaults)Check(values[p.Key].GetInt32()==(reject&&p.Key=="HomoFreedom"?3:p.Value),"default "+p.Key);foreach(string name in new[]{"ImagePointX0","WorldPointY31","CalibPointGet","RotPointTotalNum","CalibPathName","RefreshFileEnable","DisplaySettings"})Check(values[name].GetRawText()==before[name],"non-list preserved "+name);var user=JsonSerializer.Deserialize<Dictionary<string,string>>(values["ConfigurationUserData"].GetString()!)!;Check(Names.All(n=>user["@"+n]=="False")&&user["Keep"]=="value","persist modes false preserve unknown");Check(notices.Items.Last().Kind==(reject?ConfigurationNotificationKind.Error:ConfigurationNotificationKind.Success),"final notification matches write result");}
 sealed class Subs:IToolConfigurationSubscriptionService{public Dictionary<string,ConfigurationSubscriptionBinding> Bound=[];public List<string> Clears=[];public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery q)=>new(ConfigurationSubscriptionStatus.Available,[]);public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination d)=>new(ConfigurationSubscriptionStatus.Available,Bound.GetValueOrDefault(d.Name),"1");public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination d,ConfigurationSubscriptionBinding? b){if(b is null){Clears.Add(d.Name);Bound.Remove(d.Name);}else Bound[d.Name]=b;return Read(d);}}
 sealed class Confirms:IToolConfigurationConfirmationService{public bool Allow;public bool Confirm(Window? w,ConfigurationConfirmation r)=>Allow;}
 sealed class Notices:IToolConfigurationNotificationService{public List<ConfigurationNotification> Items=[];public ConfigurationNotificationResult Notify(Window? w,ConfigurationNotification n){Items.Add(n);return new(ConfigurationNotificationStatus.Displayed);}}
}
